using Xunit;
using BillingApp;
using Microsoft.Extensions.Time.Testing;

namespace BillingApp.Tests;

public class InvoiceServiceTests
{
    [Fact]
    public void Create_SetsIssuedAt()
    {
        var fakeTime = new FakeTimeProvider(new DateTimeOffset(2026, 7, 7, 12, 0, 0, TimeSpan.Zero));
        var service = new InvoiceService(fakeTime);

        var invoice = service.Create(100m);

        Assert.Equal(fakeTime.GetUtcNow(), invoice.IssuedAt);
    }
}

